namespace Spine {
	/// <summary>绘制附件时使用的颜色混合模式。</summary>
	public enum BlendMode {
		/// <summary>按透明度正常混合。</summary>
		Normal, 
			/// <summary>叠加颜色，用于发光效果。</summary>
			Additive, 
			/// <summary>正片叠底，按源色调暗目标颜色。</summary>
			Multiply, 
			/// <summary>滤色，按源色提亮目标颜色。</summary>
			Screen
	}
}
